-- Venue Live Guest "Idul Adha". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara iduladha), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'iduladha', 'Idul Adha (panggung kurban)', 'iduladha', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 119, 'center 38%',
  $t${"name":"Idul Adha","orn":"diamond","ui":{"ivory":"#FBF6E8","white":"#FFFFFF","soft":"#E6EFE1","soft2":"#B9D0B0","accent":"#1F5B3A","deep":"#0F3320","ink":"#10241A","mute":"#5E7A66","line":"#CFE0C9","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFAF0","ink":"#10241A","accent":"#1F5B3A","gold":"#C9A227","leaf":"#E6EFE1","hbg":"rgba(251,243,226,.94)","hline":"#B9D0B0","motif":"diamond"},"hud":{"bg":"rgba(15,51,32,.86)","acc":"#F2D98A","on":"#10241A"},"scr":{"wine":"#0F3320","veil":"251,243,226"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'iduladha');
update public.live_venues set decor = $d${"planter":{"url":"/assets/live-decor/iduladha/planter.webp","w":1.3,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/iduladha/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"lamp":{"url":"/assets/live-decor/iduladha/lamp.webp","w":1.3,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/iduladha/rope.webp","w":1.3,"x":3.3,"z":-6,"mirror":true},"speakers":{"url":"/assets/live-decor/iduladha/speakers.webp","w":2.4},"balloons":{"url":"/assets/live-decor/iduladha/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/iduladha/stall_snacks.webp","w":2.8},"stall_candy":{"url":"/assets/live-decor/iduladha/stall_candy.webp","w":2.6},"stall_drinks":{"url":"/assets/live-decor/iduladha/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/iduladha/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/iduladha/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/iduladha/arch.webp"},"fountain":{"url":"/assets/live-decor/iduladha/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/iduladha/sign.webp","w":1.4},"easel":{"url":"/assets/live-decor/iduladha/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/iduladha/table.webp"},"banner":{"url":"/assets/live-decor/iduladha/banner.webp","w":1.8},"gifts":{"url":"/assets/live-decor/iduladha/gifts.webp","w":2.2},"av_host":{"url":"/assets/live-decor/iduladha/av_host.webp","name":"Ananda Peci Putih"},"av_l1":{"url":"/assets/live-decor/iduladha/av_l1.webp","name":"Ananda Peci Putih"},"av_l2":{"url":"/assets/live-decor/iduladha/av_l2.webp","name":"Adik Kacamata"},"av_l3":{"url":"/assets/live-decor/iduladha/av_l3.webp","name":"Ananda Peci Hijau"},"av_l4":{"url":"/assets/live-decor/iduladha/av_l4.webp","name":"Adik Selendang Hijau"},"av_p1":{"url":"/assets/live-decor/iduladha/av_p1.webp","name":"Kakak Hijab Hijau"},"av_p2":{"url":"/assets/live-decor/iduladha/av_p2.webp","name":"Kakak Gaun